/* @autogenerated */
import { TemplateVariable } from 'app/features/template/template-variable/model/template-variable.model';
import { ConfirmAction } from 'app/shared/toolkit/action/confirm-action';
import { Component, inject } from '@angular/core';
import { TemplateVariableRepository } from 'app/features/template/template-variable/repository/template-variable-repository.service';

@Component({ selector: 'template-variable-view-enable-action', standalone: false, template: '' })
export class TemplateVariableViewEnableActionComponent extends ConfirmAction<TemplateVariable> {
  readonly name = 'enable';
  protected readonly scope = 'template/template-variable';
  protected readonly repository = inject(TemplateVariableRepository);

  protected override appliesTo(items: TemplateVariable[]) {
    return items.every((item) => !item.enabled) && true;
  }
  protected execute([item]: TemplateVariable[]) {
    return this.repository.enable(item.uid);
  }
}
